+            PlayerPrefs.SetInt(KeyCompleteFlag, 1);
+            PlayerPrefs.Save();
+            yield break;
+        }
+
+        for (; _currentStep < _steps.Count; _currentStep++)
+        {
+            var s = _steps[_currentStep];
+            clickText = s.instruction;
