+        if (missionLower.Contains("main menu")) return "Navigate to Main Menu";
+        if (missionLower.Contains("settings")) return "Open Settings";
+        if (missionLower.Contains("profile")) return "View Profile";
+        if (missionLower.Contains("shop")) return "Open Shop";
+        if (missionLower.Contains("inventory")) return "View Inventory";
+        if (missionLower.Contains("achievements")) return "View Achievements";
+        if (missionLower.Contains("leaderboard")) return "View Leaderboard";
+        if (missionLower.Contains("complete")) return "Complete Task";
+        if (missionLower.Contains("navigate")) return "Navigate UI";
+        if (missionLower.Contains("login")) return "Login";
+        if (missionLower.Contains("register")) return "Register";
+        if (missionLower.Contains("tutorial")) return "Tutorial";
+        if (missionLower.Contains("level select")) return "Level Select";
+        if (missionLower.Contains("pause")) return "Pause Game";
+        if (missionLower.Contains("resume")) return "Resume Game";
+        if (missionLower.Contains("quit")) return "Quit Game";
